            var csrfToken = "";
            var targetUrl = "";
            var targetMethod = "";
            var foundSubPost = false;
            var foundSubDelete = false;
            var els = doc.select("[hx-post], [hx-delete]");
            var btnLog = [];
            for (var i = 0; i < els.size(); i++) {
