                var hd = String(el.attr("hx-delete"));
                var url = hp || hd;
                var method = hp ? "POST" : "DELETE";
                if (!url) continue;
                btnLog.push(method + " " + url);
                if (/subscribe/i.test(url) && !/unsubscribe/i.test(url)) {
                    if (method == "POST") foundSubPost = true;
                    if (method == "DELETE") foundSubDelete = true;
                }
                var match = false;
                if (event == "addBookShelf" && method == "POST" && /subscribe/i.test(url) && !/unsubscribe/i.test(url)) match = true;
                if (event == "delBookShelf" && method == "DELETE" && /subscribe/i.test(url)) match = true;
                if (match) {
                    targetUrl = url;
                    targetMethod = method;
                    var hh = String(el.attr("hx-headers")).replace(/&quot;/g, '"').replace(/&#34;/g, '"');
                    if (hh) {
                        var cm = hh.match(/x-csrf-token["']?\s*:\s*["']([^"']+)/i);
                        if (cm) csrfToken = cm[1];
                    }
                }
            }
            if (!csrfToken) {
                var cleanHtml = String(storyHtml).replace(/&#34;/g, '"').replace(/&quot;/g, '"');
                var hc = cleanHtml.match(/x-csrf-token["']?\s*:\s*["']([^"']+)/i);
                if (hc) csrfToken = hc[1];
            }
            java.log("按钮列表: " + btnLog.join(" | "));
            if (targetUrl && targetUrl.indexOf("http") != 0) {
                targetUrl = "https://www.asianfanfics.com" + (targetUrl.charAt(0) == "/" ? "" : "/") + targetUrl;
            }
            java.log("目标: " + targetMethod + " " + targetUrl + " CSRF:" + csrfToken.length + " token:" + csrfToken.substring(0, 20));
            if (targetUrl) {
                var headerObj = {
                    "HX-Request": "true",
                    "HX-Trigger": "subscribeBtn",
                    "HX-Target": "story-vote-actions",
                    "HX-Swap": "none",
                    "HX-Current-URL": storyPageUrl,
                    "X-Requested-With": "XMLHttpRequest",
                    "Referer": storyPageUrl,
                    "Origin": "https://www.asianfanfics.com"
                };
                if (csrfToken) headerObj["X-CSRF-Token"] = csrfToken;
                var response = "";
                var statusCode = 0;
                var headerMap = new Packages.java.util.HashMap();
                for (var k in headerObj) headerMap.put(k, headerObj[k]);
                if (targetMethod == "POST") {
                    headerMap.put("Content-Type", "application/x-www-form-urlencoded");
                    var resp = java.post(targetUrl, "", headerMap);
                    statusCode = resp.statusCode();
                    response = resp.body();
                } else {
                    var cookieStr = String(cookie.getCookie(targetUrl));
                    java.log("Cookie长度: " + cookieStr.length);
                    var jsoupConn = org.jsoup.Jsoup.connect(targetUrl)
                        .method(org.jsoup.Connection.Method.DELETE)
                        .header("Cookie", cookieStr)
                        .header("HX-Request", "true")
                        .header("HX-Trigger", "subscribeBtn")
                        .header("HX-Target", "story-vote-actions")
                        .header("HX-Swap", "none")
                        .header("HX-Current-URL", storyPageUrl)
                        .header("X-CSRF-Token", csrfToken)
                        .header("X-Requested-With", "XMLHttpRequest")
                        .header("Referer", storyPageUrl)
                        .header("Origin", "https://www.asianfanfics.com")
                        .header("User-Agent", "Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36")
                        .ignoreContentType(true)
                        .ignoreHttpErrors(true);
                    var resp2 = jsoupConn.execute();
                    statusCode = resp2.statusCode();
                    response = resp2.body();
                }
                java.log("状态: " + statusCode + " 长度: " + String(response).length);
                java.log("结果: " + String(response).substring(0, 1000));
                var success = false;
                if (statusCode == 200 || statusCode == 204) {
                    if (event == "addBookShelf") {
                        success = /hx-delete/i.test(response);
                    } else {
                        var hasSubDelete = /hx-delete="[^"]*subscribe/i.test(response);
                        success = !hasSubDelete;
                    }
                }
                java.log("成功: " + success);
                if (success) {
                    java.toast(event == "addBookShelf" ? "已订阅，请下拉刷新正文" : "已取消订阅");
                } else {
                    java.toast(event == "addBookShelf" ? "订阅未成功，请重试" : "取消订阅未成功，请重试");
                }
            } else {
                if (event == "addBookShelf" && foundSubDelete) {
                    java.toast("已订阅，无需重复订阅");
                } else if (event == "delBookShelf" && foundSubPost && !foundSubDelete) {
                    java.toast("未订阅，无需取消");
                } else {
                    java.toast("未找到订阅按钮，请检查登录状态");
                }
            }
        } catch (e) {
            java.log("失败: " + e);
            java.toast("失败: " + e);
        }
    }
